wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(97799061864216841318)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Calcular KPIs'
,p_static_id=>'calcular-kpis'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'  SELECT COUNT(DISTINCT id_bar) INTO :P10_BARES_VISITADOS',
'  FROM Visitas WHERE id_bebedor = :G_BEBEDOR_ID;',
'',
'  SELECT NVL(SUM(total_consumos), 0) INTO :P10_TOTAL_CONSUMOS',
'  FROM Visitas WHERE id_bebedor = :G_BEBEDOR_ID;',
'',
'  BEGIN',
'    SELECT b.nombre INTO :P10_BAR_FAVORITO',
'    FROM Visitas v JOIN Bares b ON b.id = v.id_bar',
'    WHERE v.id_bebedor = :G_BEBEDOR_ID',
'    GROUP BY b.id, b.nombre',
'    ORDER BY COUNT(*) DESC',
'    FETCH FIRST 1 ROW ONLY;',
unistr('  EXCEPTION WHEN NO_DATA_FOUND THEN :P10_BAR_FAVORITO := ''Sin visitas a\00FAn'';'),
'  END;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>19672172282675532719
);
end;
